import{z as p,x as A,o as E,c as d,q as s,j as o,D as r,d as l,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Earley 解析","description":"","frontmatter":{"title":"Earley 解析","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/earley-parser.md","filePath":"cs/earley-parser.md","lastUpdated":1791413859000}'),B={name:"cs/earley-parser.md"};function C(c,a,h,m,y,F){const t=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=s('<h1 id="earley-解析" tabindex="-1">Earley 解析 <a class="header-anchor" href="#earley-解析" aria-label="Permalink to &quot;Earley 解析&quot;">​</a></h1><div class="epigraph"><p>每一输入位置一张项集：预测、扫描、完成三步推进；任意 CFG 可在立方时间内判定成员，无二义时降到平方。</p><footer>—— 据 Earley, An Efficient Context-Free Parsing Algorithm, 1970；龙书对一般 CFG 分析的对照整理</footer></div><p>上一课<a href="/cs/yacc-bison">yacc / bison</a>要求文法落进 LALR，冲突靠改写或 <code>%left</code>。主干<a href="/cs/cyk-parsing">CYK</a>已证明一般 CFL 可判定，但要 Chomsky 范式。缺口是<strong>不改写文法</strong>的通用分析：Earley 项在原 CFG 上跑，认左递归、认 ε，也认 yacc 拒掉的形状。本课钉项与三步，不把 marpa 实现写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LALR 失败时人改文法，语义动作跟着碎。Earley：项 \\([A\\to\\alpha\\cdot\\beta,\\,j]\\) 挂在位置 \\(i\\)，表示 \\(A\\to\\alpha\\beta\\) 从 \\(j\\) 开始，已吃到 \\(i\\)。预测：点后非终结符则加入其产生式；扫描：点后终结符与当前记号匹配则前进；完成：点到末尾，把等待该非终结符的项推进。缺口是这套动态规划，不是再造 LALR 表。</p><p>复杂度：一般 \\(O(n^3)\\)，无二义 \\(O(n^2)\\)，确定（近似 LR）可近线性。比 CYK 省 CNF 化；比 bison 慢，换的是「任意 CFG」。</p><h3 id="项带起点-不只带点" tabindex="-1">项带起点，不只带点 <a class="header-anchor" href="#项带起点-不只带点" aria-label="Permalink to &quot;项带起点，不只带点&quot;">​</a></h3><p>LR 项活在生成期 DFA 状态里；Earley 项活在输入位置上，起点 \\(j\\) 记录「这段从哪预测」。丢掉 \\(j\\) 就无法完成。这不是 lex 的 DFA 状态。</p><p><span class="marginnote">项可以直译成「进度条」：规则 E → E + T 加一个点 ·，点左边是已经认过的部分，右边是还在等的部分；逗号后的 j 记录这条规则从第几个词开始认。丢掉 j，规则认完了都不知道该回去推进哪条上级规则——完成步会瞎。</span></p><p><span class="marginnote">「完成」一步的实体过程：扫描出的完成项回到起点 j 所在的项集，把所有点后正等着这个非终结符的项各推进一格。下图用 id 开头的输入走一遍。</span></p>',10)),(E(),o(n,null,{default:r(()=>[i(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22S1%20%E6%89%AB%E6%8F%8F%E5%87%BA%E5%AE%8C%E6%88%90%E9%A1%B9%EF%BC%9AT%20%E2%86%92%20id%20%C2%B7%EF%BC%8C%E8%B5%B7%E7%82%B9%200%22%5D%20--%3E%20B%5B%22%E5%9B%9E%E5%88%B0%20S0%EF%BC%9A%E8%B0%81%E7%9A%84%E7%82%B9%E5%90%8E%E6%AD%A3%E7%AD%89%E7%9D%80%20T%EF%BC%9F%22%5D%0A%20%20B%20--%3E%20C%5B%22S0%20%E7%9A%84%E9%A1%B9%EF%BC%9AE%20%E2%86%92%20%C2%B7%20T%EF%BC%8C%E8%B5%B7%E7%82%B9%200%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%AE%8C%E6%88%90%EF%BC%9A%E6%8A%8A%E5%AE%83%E7%9A%84%E7%82%B9%E6%8E%A8%E8%BF%87%20T%22%5D%0A%20%20D%20--%3E%20E%5B%22S1%20%E6%96%B0%E5%A2%9E%EF%BC%9AE%20%E2%86%92%20T%20%C2%B7%EF%BC%8C%E8%B5%B7%E7%82%B9%200%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"Earley 1970（CACM）。Leo 的右递归优化改善确定情形。龙书把 Earley 当一般方法，编译器前端仍偏 LR；本进阶课要的是 yacc 覆盖不了时的退路。")],-1)),a[4]||(a[4]=e("h2",{id:"方法",tabindex:"-1"},[l("方法 "),e("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),a[5]||(a[5]=e("p",null,"对 \\(i=0\\ldots n\\) 维护项集 \\(S_i\\)。\\(S_0\\) 放入增广产生式的点在左端。循环执行预测/扫描/完成直到闭包。接受：结束位置含 \\([S'\\to S\\cdot,\\,0]\\)。建树：完成步记下前驱指针，事后回溯；二义则森林。",-1)),(E(),o(n,null,{default:r(()=>[i(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22%E4%BB%BB%E6%84%8F%20CFG%22%5D%20--%3E%20S0%5B%22S0%20%E9%A2%84%E6%B5%8B%22%5D%0A%20%20S0%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%E8%AE%B0%E5%8F%B7%22%5D%0A%20%20SCAN%20--%3E%20COMP%5B%22%E5%AE%8C%E6%88%90%22%5D%0A%20%20COMP%20--%3E%20PRED%5B%22%E5%86%8D%E9%A2%84%E6%B5%8B%22%5D%0A%20%20PRED%20--%3E%20ACC%5B%22%E6%88%90%E5%91%98%20%2F%20%E6%A3%AE%E6%9E%97%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p>不要把 Earley 当「带回溯的递归下降」：它是按位置的闭包，共享子项，不是指数分叉的朴素搜索。</p><p><span class="marginnote">两者的差别可以类比「共享笔记」：递归下降走错路就倒回去重走，同一个前缀可能重算多遍；Earley 把每个位置所有可能的进度都记在同一张项集里，重复的项只留一份。正因共享，它才敢给出立方时间上界，而朴素回溯最坏是指数。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ε 产生式在预测与完成里要小心重复加入，否则不终止。二义文法给出多棵树，Earley 本身不消二义——消二义是优先级或后课 GLR 的用户规则。</p><p><span class="marginnote">初学者容易以为「二义文法会让 Earley 报错」。实际上它照常解析，只是完成时给出多棵语法树（森林）——挑哪棵、按什么优先级挑，是用户层的消歧规则，算法本身不替你决定。bison 的冲突报错是生成器层的声明，两回事。</span></p><p>与 CYK：格子是非终结符×区间；Earley 格子是项×位置。二者都是 CFL 成员的 DP，形状不同。编程语言若已是 LALR，没有理由默认 Earley。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GLR 的分叉栈，不把 PEG 的有序选择当 CFG。不证 Earley 与 CYK 的渐近常数谁优。后课默认：任意 CFG 可 Earley；实用确定文法仍用生成器。下一课 GLR：在 LR 表上对冲突分叉，而不是换一套项。</p><p>工具：部分语言工作台用 Earley/GLL；编辑器增量解析后课再接。此处只要求会画三步。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Earley：按位置闭包项集，认任意 CFG。</li><li>三步：预测、扫描、完成；一般立方。</li><li>不替代 bison：LALR 足够时不必通用算法。</li><li>出处：Earley, 1970；对照 Aho et al. 与 Kasami/Younger。</li></ul>',11))])}const u=p(B,[["render",C]]);export{D as __pageData,u as default};
